<?php
namespace CloudHost247\Ovh\Services;use InvalidArgumentException;
final class ReverseDnsManager
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}function set($endpointId,$ipBlock,$ip,$reverse,$confirmed){if(!$confirmed)throw new InvalidArgumentException('Explicit reverse-DNS confirmation is required.');$this->validate($ipBlock,$ip);if(!filter_var($reverse,FILTER_VALIDATE_DOMAIN,FILTER_FLAG_HOSTNAME))throw new InvalidArgumentException('Invalid reverse hostname.');return$this->r->endpoint($endpointId)->post('/ip/'.rawurlencode($ipBlock).'/reverse',array('ipReverse'=>$ip,'reverse'=>$reverse));}function delete($endpointId,$ipBlock,$ip,$confirmed){if(!$confirmed)throw new InvalidArgumentException('Explicit reverse-DNS deletion confirmation is required.');$this->validate($ipBlock,$ip);return$this->r->endpoint($endpointId)->delete('/ip/'.rawurlencode($ipBlock).'/reverse/'.rawurlencode($ip));}private function validate($b,$i){if(!filter_var(explode('/',$b)[0],FILTER_VALIDATE_IP)||!filter_var($i,FILTER_VALIDATE_IP))throw new InvalidArgumentException('Invalid IP block or address.');}}
